<?php $pages = max( 1, (int) ceil( $rows['total'] / $rows['per_page'] ) ); ?>
<form method="get" data-admitad-ajax data-admitad-action="promokodiki_admitad_admin" data-admitad-operation="rule_list" data-admitad-page="admitad-rules" data-admitad-fragment="rules-table"><input type="hidden" name="post_type" value="promocode"><input type="hidden" name="page" value="admitad-rules"><input type="hidden" name="s" value="<?php echo esc_attr( $request->search() ); ?>"><input type="hidden" name="status" value="<?php echo esc_attr( $request->filter( 'status' ) ); ?>"><label>Строк на странице <select name="per_page"><?php foreach ( array( 20, 50, 100 ) as $size ) : ?><option value="<?php echo esc_attr( (string) $size ); ?>"<?php selected( $request->per_page(), $size ); ?>><?php echo esc_html( (string) $size ); ?></option><?php endforeach; ?></select></label><button class="button">Применить</button></form>
<table class="widefat striped"><thead><tr><th>Фраза</th><th>Рубрика</th><th>Режим / вес</th><th>Доказательства</th><th>Статус</th><th>Действия</th></tr></thead><tbody><?php if ( empty( $rows['items'] ) ) : ?><tr><td colspan="6">Правила не найдены.</td></tr><?php endif; foreach ( $rows['items'] as $row ) : $badge = Promokodiki_Admitad_Admin_Presenter::status( 'rule', (string) $row['status'] ); ?><tr><td><?php echo esc_html( $row['normalized_phrase'] ); ?></td><td><?php echo esc_html( Promokodiki_Admitad_Admin_Presenter::term_path( (int) $row['site_term_id'] ) ); ?></td><td><?php echo esc_html( $row['match_mode'] . ' / ' . $row['weight'] ); ?></td><td><?php echo esc_html( $row['evidence_count'] . ' / ' . $row['distinct_campaign_count'] . ' / ' . $row['contradiction_count'] ); ?></td><td><span class="<?php echo esc_attr( $badge['class'] ); ?>"><?php echo esc_html( $badge['label'] ); ?></span></td><td><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" data-admitad-ajax data-admitad-action="promokodiki_admitad_admin" data-admitad-operation="<?php echo 'archived' === $row['status'] ? 'rule_restore' : 'rule_archive'; ?>" data-admitad-page="admitad-rules" data-admitad-fragment="rules-table"><input type="hidden" name="action" value="promokodiki_admitad_mapping_action"><input type="hidden" name="operation" value="<?php echo 'archived' === $row['status'] ? 'restore_rule' : 'archive_rule'; ?>"><?php wp_nonce_field( 'promokodiki_admitad_mapping_action' ); ?><input type="hidden" name="rule_id" value="<?php echo esc_attr( (string) $row['id'] ); ?>"><button class="button"><?php echo esc_html( 'archived' === $row['status'] ? 'Восстановить (приостановить)' : 'Архивировать' ); ?></button></form></td></tr><?php endforeach; ?></tbody></table>
<?php if ( $pages > 1 ) : ?><nav><?php for ( $i = 1; $i <= $pages; ++$i ) : $url = add_query_arg( 'paged', $i, $request->url() ); ?><a href="<?php echo esc_url( $url ); ?>" data-admitad-ajax data-admitad-action="promokodiki_admitad_admin" data-admitad-operation="rule_list" data-admitad-page="admitad-rules" data-admitad-fragment="rules-table"><?php echo esc_html( (string) $i ); ?></a> <?php endfor; ?></nav><?php endif; ?>
